<?php require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../config/koneksi.php'; require_once __DIR__ . '/../includes/functions.php'; if($_SERVER['REQUEST_METHOD']!=='POST') redirect('anggota.php'); validate_csrf(); $id=(int)($_POST['id']??0); $nama=trim($_POST['nama']??''); $jabatan=trim($_POST['jabatan']??''); $kelas=trim($_POST['kelas']??''); $foto=$_POST['foto_lama']??''; try{ if(!empty($_FILES['foto']['name'])){ $baru=upload_image($_FILES['foto'],'../uploads/'); if($baru){ delete_upload($foto); $foto=$baru; } } db_query($conn,'UPDATE anggota_osis SET nama=?, jabatan=?, kelas=?, foto=? WHERE id=?',[$nama,$jabatan,$kelas,$foto,$id]); redirect('anggota.php'); } catch(Exception $e){ die('Gagal update anggota: '.e($e->getMessage())); }
